package com.cpf.starter.integration.realtime;
import java.security.Principal; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/cpf/realtime") public class CpfRealtimeController { private final CpfRealtimeHub hub; public CpfRealtimeController(CpfRealtimeHub h){hub=h;} @GetMapping(value="/{topic}",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter subscribe(@PathVariable String topic,@RequestHeader(value="X-CPF-Tenant-Id",required=false) String tenant,@RequestHeader(value="Last-Event-ID",required=false) String last,Principal principal){if(principal==null)throw new SecurityException("authenticated principal required");return hub.subscribe(topic,tenant,principal.getName(),last);} }
